-- Published guidance remains public. Draft content and audit access require a content role
-- AND a second-factor-verified session. The role remains readable by its owner for enrollment.
alter policy "Content editors read all guidance" on public.finnest_guidance using (((select auth.jwt()) ->> 'aal' = 'aal2') and exists (select 1 from public.finnest_admin_roles r where r.user_id = (select auth.uid()) and r.role in ('super_admin','content_manager')));
alter policy "Content editors create guidance" on public.finnest_guidance with check (((select auth.jwt()) ->> 'aal' = 'aal2') and exists (select 1 from public.finnest_admin_roles r where r.user_id = (select auth.uid()) and r.role in ('super_admin','content_manager')));
alter policy "Content editors update guidance" on public.finnest_guidance using (((select auth.jwt()) ->> 'aal' = 'aal2') and exists (select 1 from public.finnest_admin_roles r where r.user_id = (select auth.uid()) and r.role in ('super_admin','content_manager'))) with check (((select auth.jwt()) ->> 'aal' = 'aal2') and exists (select 1 from public.finnest_admin_roles r where r.user_id = (select auth.uid()) and r.role in ('super_admin','content_manager')));
alter policy "Content editors read audit" on public.finnest_admin_audit using (((select auth.jwt()) ->> 'aal' = 'aal2') and exists (select 1 from public.finnest_admin_roles r where r.user_id = (select auth.uid()) and r.role in ('super_admin','content_manager')));
